        if (mOutPtr == DEPTH - 2)
            full_n <= 1'b0;
    end
    else if (~push & pop)
        full_n <= 1'b1;
end

// almost_full_n 

// empty_n
always @(posedge clk ) begin
    if (reset == 1'b1)
        empty_n <= 1'b0;
    else if (push & ~pop)
        empty_n <= 1'b1;
    else if (~push & pop) begin
        if (mOutPtr == 0)
            empty_n <= 1'b0;
    end
